def transpose(text):
    lines = text.split("\n")
    width = max((len(line) for line in lines), default=0)
    padded = [line.ljust(width) for line in lines]
    rows = []
    for i in range(width):
        rows.append("".join(line[i] for line in padded))
    return "\n".join(rows)
